#define _POSIX_C_SOURCE 200809L
#include <glob.h>
#include <inttypes.h>
#include <limits.h>
#include <openssl/sha.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <zstd.h>

#define RAM_SIZE 0x200000u
#define PLAYER 0x0a6500u
#define LIVE_TABLE 0x090748u
#define ACTOR_BASE_KSEG 0x8009fd80u
#define PROP_START 0x8005c258u
#define PROP_END 0x8005c58cu
#define MAX_SAMPLES 4096u
#define MAX_ACTORS 64u
#define MAX_FLOW 256u
#define MAX_SUM 128u

typedef struct { const uint8_t *p,*end; const char *path; } Reader;
typedef struct { uint32_t ptr; int32_t x,y,z,vx,vy,vz,field40; uint16_t flags,field5e; uint8_t id,eligible; } Actor;
typedef struct {
    uint64_t frame,cycle,handler_blocks; uint32_t movie,pc,player_lift_hits,actor_lift_hits,lower_band_checks;
    int32_t x,y,z,vx,vy,vz,carry_offset; uint16_t mode,contact,timer84,action88,latch9e; uint8_t live_count,eligible_count;
    Actor actor[MAX_ACTORS];
} Sample;
typedef struct { uint32_t pc; uint64_t count; uint32_t frames; } Flow;
typedef struct { uint32_t ptr; uint8_t id; uint32_t first,last,frames,eligible_frames,minus512; int32_t min_y,max_y,min_vy,max_vy; uint16_t flags_or; } ActorSum;

static Sample samples[MAX_SAMPLES]; static size_t ns;
static Flow flows[MAX_FLOW]; static size_t nf;
static ActorSum sums[MAX_SUM]; static size_t nsum;
static uint8_t *dom[4]; static uint32_t dsz[4]; static uint64_t hash_checks,changed_runs;

static void die(const char *m,const char *p){fprintf(stderr,"phase4_b02_capsule_probe: %s%s%s\n",m,p?": ":"",p?p:"");exit(1);}
static void need(Reader*r,size_t n){if((size_t)(r->end-r->p)<n)die("truncated chunk",r->path);} static uint8_t u8(Reader*r){need(r,1);return*r->p++;}
static uint16_t u16(Reader*r){need(r,2);uint16_t v=r->p[0]|((uint16_t)r->p[1]<<8);r->p+=2;return v;} static uint32_t u32(Reader*r){need(r,4);uint32_t v=r->p[0]|((uint32_t)r->p[1]<<8)|((uint32_t)r->p[2]<<16)|((uint32_t)r->p[3]<<24);r->p+=4;return v;} static uint64_t u64(Reader*r){uint64_t a=u32(r),b=u32(r);return a|(b<<32);} static const uint8_t*take(Reader*r,size_t n){need(r,n);const uint8_t*p=r->p;r->p+=n;return p;}
static uint16_t rd16(const uint8_t*p){return p[0]|((uint16_t)p[1]<<8);} static uint32_t rd32(const uint8_t*p){return p[0]|((uint32_t)p[1]<<8)|((uint32_t)p[2]<<16)|((uint32_t)p[3]<<24);} static int32_t rd32s(const uint8_t*p){return(int32_t)rd32(p);}
static uint32_t phys(uint32_t p){return p&0x1fffffu;} static int valid_ptr(uint32_t p,size_t n){uint32_t q=phys(p);return (p&0xffe00000u)==0x80000000u && (uint64_t)q+n<=RAM_SIZE;}

static uint8_t*decomp(const char*path,size_t*out){struct stat st;if(stat(path,&st)||st.st_size<=0)die("cannot stat",path);FILE*f=fopen(path,"rb");if(!f)die("cannot open",path);uint8_t*s=malloc(st.st_size);if(!s)die("oom",0);if(fread(s,1,st.st_size,f)!=(size_t)st.st_size)die("cannot read",path);fclose(f);unsigned long long n=ZSTD_getFrameContentSize(s,st.st_size);if(n==ZSTD_CONTENTSIZE_ERROR||n==ZSTD_CONTENTSIZE_UNKNOWN||n>SIZE_MAX)die("bad zstd size",path);uint8_t*d=malloc((size_t)n);if(!d)die("oom",0);size_t got=ZSTD_decompress(d,(size_t)n,s,st.st_size);free(s);if(ZSTD_isError(got)||got!=(size_t)n)die("zstd decode",path);*out=got;return d;}
static void add_flow(uint32_t pc,uint64_t count){if(pc<PROP_START||pc>=PROP_END)return;for(size_t i=0;i<nf;i++)if(flows[i].pc==pc){flows[i].count+=count;flows[i].frames++;return;}if(nf>=MAX_FLOW)die("too many flow pcs",0);flows[nf++]=(Flow){pc,count,1};}
static Actor read_actor(const uint8_t*ram,uint32_t ptr){Actor a={0};a.ptr=ptr;if(!valid_ptr(ptr,0x60))return a;const uint8_t*p=ram+phys(ptr);a.id=p[0];a.x=rd32s(p+4);a.y=rd32s(p+8);a.z=rd32s(p+12);a.vx=rd32s(p+0x1c);a.vy=rd32s(p+0x20);a.vz=rd32s(p+0x24);a.field40=rd32s(p+0x40);a.flags=rd16(p+0x5c);a.field5e=rd16(p+0x5e);a.eligible=(a.flags&0x20)&&a.field40==0;return a;}
static void capture(uint64_t frame,uint64_t cycle,uint32_t movie,uint32_t pc,uint64_t blocks){if(ns>=MAX_SAMPLES)die("too many samples",0);const uint8_t*ram=dom[1];if(!ram||dsz[1]!=RAM_SIZE)die("bad ram domain",0);Sample*s=&samples[ns++];memset(s,0,sizeof(*s));s->frame=frame;s->cycle=cycle;s->movie=movie;s->pc=pc;s->handler_blocks=blocks;s->x=rd32s(ram+PLAYER);s->y=rd32s(ram+PLAYER+4);s->z=rd32s(ram+PLAYER+8);s->vx=rd32s(ram+PLAYER+0x2c);s->vy=rd32s(ram+PLAYER+0x30);s->vz=rd32s(ram+PLAYER+0x34);s->carry_offset=rd32s(ram+PLAYER+0x5c);s->mode=rd16(ram+PLAYER+0x80);s->contact=rd16(ram+PLAYER+0x82);s->timer84=rd16(ram+PLAYER+0x84);s->action88=rd16(ram+PLAYER+0x88);s->latch9e=rd16(ram+PLAYER+0x9e);for(unsigned i=0;i<MAX_ACTORS;i++){uint32_t ptr=rd32(ram+LIVE_TABLE+i*4);if(!ptr)break;if(!valid_ptr(ptr,0x60))die("invalid live actor pointer",0);s->actor[s->live_count]=read_actor(ram,ptr);if(s->actor[s->live_count].eligible)s->eligible_count++;s->live_count++;}}
static void chunk(const char*path,uint32_t*want_mode,uint32_t*want_regs){size_t n;uint8_t*raw=decomp(path,&n);Reader r={raw,raw+n,path};if(memcmp(take(&r,8),"DSTCAP01",8))die("bad magic",path);if(u32(&r)!=1)die("bad version",path);uint32_t mode=u32(&r);(void)u64(&r);uint32_t regs=u32(&r);for(uint32_t i=0;i<regs;i++){uint16_t z=u16(&r);(void)take(&r,z);}if(*want_mode==UINT32_MAX){*want_mode=mode;*want_regs=regs;}else if(mode!=*want_mode||regs!=*want_regs)die("schema drift",path);while(r.p<r.end){if(u8(&r)!=1)die("bad record",path);uint64_t frame=u64(&r),cycle=u64(&r);uint32_t movie=u32(&r),pc=u32(&r);(void)u32(&r);for(uint32_t i=0;i<regs;i++)(void)u32(&r);for(int q=0;q<3;q++){uint32_t id=u32(&r),sz=u32(&r),runs=u32(&r);const uint8_t*expect=take(&r,32);if(id<1||id>3)die("bad domain",path);if(!dom[id]){dom[id]=calloc(1,sz);dsz[id]=sz;if(!dom[id])die("oom",0);}if(dsz[id]!=sz)die("domain size drift",path);for(uint32_t j=0;j<runs;j++){uint32_t off=u32(&r),len=u32(&r);const uint8_t*data=take(&r,len);if((uint64_t)off+len>sz)die("delta range",path);memcpy(dom[id]+off,data,len);changed_runs++;}uint8_t actual[32];SHA256(dom[id],sz,actual);if(memcmp(actual,expect,32))die("domain hash mismatch",path);hash_checks++;}uint64_t count=u64(&r),blocks=0;uint32_t player_hits=0,actor_hits=0,lower_checks=0;for(uint64_t i=0;i<count;i++){uint32_t fpc=u32(&r);uint64_t hits;if(mode==2){uint32_t ins=u32(&r);(void)u64(&r);hits=ins;}else if(mode==1)hits=u64(&r);else if(mode==0)hits=0;else die("bad block mode",path);if(fpc>=PROP_START&&fpc<PROP_END){add_flow(fpc,hits);blocks+=hits;if(fpc==0x8005c3d0u)player_hits+=(uint32_t)hits;if(fpc==0x8005c4e0u)actor_hits+=(uint32_t)hits;if(fpc==0x8005c3b4u)lower_checks+=(uint32_t)hits;}}capture(frame,cycle,movie,pc,blocks);samples[ns-1].player_lift_hits=player_hits;samples[ns-1].actor_lift_hits=actor_hits;samples[ns-1].lower_band_checks=lower_checks;}free(raw);}
static const Actor*find_actor(const Sample*s,uint32_t ptr){for(unsigned i=0;i<s->live_count;i++)if(s->actor[i].ptr==ptr)return&s->actor[i];return 0;}
static ActorSum*sum_for(const Actor*a,uint32_t movie){for(size_t i=0;i<nsum;i++)if(sums[i].ptr==a->ptr)return&sums[i];if(nsum>=MAX_SUM)die("too many actor identities",0);ActorSum*z=&sums[nsum++];*z=(ActorSum){.ptr=a->ptr,.id=a->id,.first=movie,.last=movie,.min_y=a->y,.max_y=a->y,.min_vy=a->vy,.max_vy=a->vy};return z;}
static int cmp_flow(const void*a,const void*b){uint32_t x=((const Flow*)a)->pc,y=((const Flow*)b)->pc;return x<y?-1:x>y;}
static void print_actor(const Actor*a){if(!a){printf("null");return;}printf("{\"ptr\":\"0x%08x\",\"id\":%u,\"pos\":[%d,%d,%d],\"vel\":[%d,%d,%d],\"flags\":\"0x%04x\",\"field40\":%d,\"field5e\":%u,\"eligible\":%s}",a->ptr,a->id,a->x,a->y,a->z,a->vx,a->vy,a->vz,a->flags,a->field40,a->field5e,a->eligible?"true":"false");}

int main(int argc,char**argv){if(argc!=2){fprintf(stderr,"usage: %s CAPSULE_DIR\n",argv[0]);return 2;}char pat[PATH_MAX];if(snprintf(pat,sizeof(pat),"%s/chunks/*.tcap.zst",argv[1])>=(int)sizeof(pat))die("path long",argv[1]);glob_t g;if(glob(pat,0,0,&g)||!g.gl_pathc)die("no chunks",pat);uint32_t mode=UINT32_MAX,regs=0;for(size_t i=0;i<g.gl_pathc;i++)chunk(g.gl_pathv[i],&mode,&regs);qsort(flows,nf,sizeof(*flows),cmp_flow);
    for(size_t i=0;i<ns;i++)for(unsigned j=0;j<samples[i].live_count;j++){Actor*a=&samples[i].actor[j];ActorSum*z=sum_for(a,samples[i].movie);z->last=samples[i].movie;z->frames++;z->eligible_frames+=a->eligible;z->flags_or|=a->flags;if(a->y<z->min_y)z->min_y=a->y;if(a->y>z->max_y)z->max_y=a->y;if(a->vy<z->min_vy)z->min_vy=a->vy;if(a->vy>z->max_vy)z->max_vy=a->vy;if(i){const Actor*p=find_actor(&samples[i-1],a->ptr);if(p&&a->vy-p->vy==-512)z->minus512++;}}
    uint32_t first5=UINT32_MAX,last5=0,mode5_frames=0,handler_frames=0,eligible_frames=0,carry_frames=0,detach_events=0,land_events=0,player_lift_frames=0,actor_lift_frames=0,lower_check_frames=0;uint64_t player_lift_hits=0,actor_lift_hits=0;int32_t ymin=INT32_MAX,ymax=INT32_MIN,vymin=INT32_MAX,vymax=INT32_MIN;
    for(size_t i=0;i<ns;i++){Sample*s=&samples[i];if(s->y<ymin)ymin=s->y;if(s->y>ymax)ymax=s->y;if(s->vy<vymin)vymin=s->vy;if(s->vy>vymax)vymax=s->vy;if(s->mode==5){if(first5==UINT32_MAX)first5=s->movie;last5=s->movie;mode5_frames++;}handler_frames+=!!s->handler_blocks;eligible_frames+=!!s->eligible_count;carry_frames+=s->carry_offset>0;player_lift_frames+=!!s->player_lift_hits;actor_lift_frames+=!!s->actor_lift_hits;lower_check_frames+=!!s->lower_band_checks;player_lift_hits+=s->player_lift_hits;actor_lift_hits+=s->actor_lift_hits;if(i&&samples[i-1].carry_offset>0&&s->carry_offset==0)detach_events++;if(i&&samples[i-1].mode==5&&s->mode!=5)land_events++;}
    printf("{\n  \"schema\":\"abl-phase4-b02-capsule-probe-v1\",\n  \"capsule\":\"%s\",\n",argv[1]);printf("  \"validation\":{\"chunks\":%zu,\"records\":%zu,\"block_mode\":%u,\"register_count\":%u,\"domain_hashes_checked\":%"PRIu64",\"changed_runs\":%"PRIu64",\"parse_exact\":true},\n",g.gl_pathc,ns,mode,regs,hash_checks,changed_runs);printf("  \"trajectory\":{\"first_movie_frame\":%u,\"last_movie_frame\":%u,\"player_y_min\":%d,\"player_y_max\":%d,\"player_vy_min\":%d,\"player_vy_max\":%d},\n",samples[0].movie,samples[ns-1].movie,ymin,ymax,vymin,vymax);printf("  \"coverage\":{\"handler_sample_frames\":%u,\"player_lift_frames\":%u,\"player_lift_hits\":%"PRIu64",\"lower_band_check_frames\":%u,\"actor_lift_frames\":%u,\"actor_lift_hits\":%"PRIu64",\"mode5_frames\":%u,\"mode5_first\":%u,\"mode5_last\":%u,\"eligible_actor_frames\":%u,\"carry_frames\":%u,\"carry_detach_events\":%u,\"mode5_exit_events\":%u},\n",handler_frames,player_lift_frames,player_lift_hits,lower_check_frames,actor_lift_frames,actor_lift_hits,mode5_frames,first5,last5,eligible_frames,carry_frames,detach_events,land_events);
    printf("  \"handler_flow\":[");for(size_t i=0;i<nf;i++){if(i)putchar(',');printf("{\"pc\":\"0x%08x\",\"count\":%"PRIu64",\"frames\":%u}",flows[i].pc,flows[i].count,flows[i].frames);}printf("],\n  \"actor_summaries\":[");int first=1;for(size_t i=0;i<nsum;i++){ActorSum*z=&sums[i];if(!z->eligible_frames&&z->minus512==0)continue;if(!first)putchar(',');first=0;printf("{\"ptr\":\"0x%08x\",\"id\":%u,\"first\":%u,\"last\":%u,\"frames\":%u,\"eligible_frames\":%u,\"exact_minus512_frame_deltas\":%u,\"y_min\":%d,\"y_max\":%d,\"vy_min\":%d,\"vy_max\":%d,\"flags_or\":\"0x%04x\"}",z->ptr,z->id,z->first,z->last,z->frames,z->eligible_frames,z->minus512,z->min_y,z->max_y,z->min_vy,z->max_vy,z->flags_or);}printf("],\n  \"player_lift_frames\":[");first=1;for(size_t i=0;i<ns;i++){Sample*s=&samples[i];if(!s->player_lift_hits)continue;if(!first)putchar(',');first=0;printf("{\"movie\":%u,\"emulator_frame\":%"PRIu64",\"hits\":%u,\"y\":%d,\"vy\":%d,\"mode\":%u,\"contact\":%u,\"latch9e\":%u,\"lower_band_check\":%s}",s->movie,s->frame,s->player_lift_hits,s->y,s->vy,s->mode,s->contact,s->latch9e,s->lower_band_checks?"true":"false");}printf("],\n  \"actor_lift_frames\":[");first=1;for(size_t i=0;i<ns;i++){Sample*s=&samples[i];if(!s->actor_lift_hits)continue;if(!first)putchar(',');first=0;printf("{\"movie\":%u,\"emulator_frame\":%"PRIu64",\"hits\":%u,\"eligible_actors\":[",s->movie,s->frame,s->actor_lift_hits);int af=1;for(unsigned j=0;j<s->live_count;j++)if(s->actor[j].eligible){if(!af)putchar(',');af=0;print_actor(&s->actor[j]);}printf("]}");}printf("],\n  \"mode_spans\":[");size_t start=0;first=1;while(start<ns){size_t end=start;while(end+1<ns&&samples[end+1].mode==samples[start].mode)end++;if(!first)putchar(',');first=0;printf("{\"mode\":%u,\"first\":%u,\"last\":%u,\"frames\":%zu,\"start_y\":%d,\"end_y\":%d}",samples[start].mode,samples[start].movie,samples[end].movie,end-start+1,samples[start].y,samples[end].y);start=end+1;}printf("],\n  \"events\":[\n");first=1;for(size_t i=1;i<ns;i++){Sample*p=&samples[i-1],*s=&samples[i];int evt=s->mode!=p->mode||s->carry_offset!=p->carry_offset||s->eligible_count!=p->eligible_count;if(!evt)continue;if(!first)printf(",\n");first=0;printf("    {\"movie\":%u,\"emulator_frame\":%"PRIu64",\"player\":{\"pos\":[%d,%d,%d],\"vel\":[%d,%d,%d],\"mode\":%u,\"contact\":%u,\"timer84\":%u,\"action88\":%u,\"latch9e\":%u},\"carry_before\":%d,\"carry_after\":%d,\"eligible_before\":%u,\"eligible_after\":%u",s->movie,s->frame,s->x,s->y,s->z,s->vx,s->vy,s->vz,s->mode,s->contact,s->timer84,s->action88,s->latch9e,p->carry_offset,s->carry_offset,p->eligible_count,s->eligible_count);if(p->carry_offset>0){uint32_t ptr=ACTOR_BASE_KSEG+(uint32_t)p->carry_offset;printf(",\"carried_actor_before\":");print_actor(find_actor(p,ptr));printf(",\"same_actor_after\":");print_actor(find_actor(s,ptr));}printf("}");}printf("\n  ]\n}\n");globfree(&g);for(int i=1;i<=3;i++)free(dom[i]);return 0;}
